import { Button, Card, Stack, applyPalette } from "@arachnejs/ui";
import "@arachnejs/ui/styles.css";

applyPalette("graphite");

<Stack gap="1rem">
  <Button>Primary</Button>
  <Card>Hello</Card>
</Stack>

import { applyPalette, applyRadius, paletteStyle } from "@arachnejs/ui";

applyPalette("graphite"); // default
applyPalette("marina");
applyRadius("sm"); // none | sm | lg — sm is default
applyPalette({ accent: "#0ea5e9", canvas: "#f8fafc", radius: "lg" });

<div style={paletteStyle("lagoon")}>Scoped theme</div>
